package com.hrm.service.impl;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.hrm.dto.profile.*; import com.hrm.entity.*; import com.hrm.exception.BadRequestException; import com.hrm.exception.ResourceNotFoundException; import com.hrm.repository.*; import com.hrm.security.UserPrincipal; import com.hrm.service.*;
import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class ProfileChangeRequestServiceImpl implements ProfileChangeRequestService {
 private final ProfileChangeRequestRepository requests; private final UserRepository users; private final EmployeeProfileService profiles; private final NotificationService notifications; private final ObjectMapper mapper;
 public ProfileChangeRequestResponse submit(EmployeeProfileRequest request,UserPrincipal current){ if(current==null) throw new BadRequestException("Unauthorized"); if("ADMIN".equalsIgnoreCase(current.getSystemRole())) throw new BadRequestException("Admin cập nhật trực tiếp hồ sơ nhân sự."); User requester=users.findById(current.getId()).orElseThrow(()->new ResourceNotFoundException("User not found")); Map<String,Object> data=mapper.convertValue(request,new TypeReference<>(){}); ProfileChangeRequest saved=requests.save(ProfileChangeRequest.builder().requester(requester).requestedData(data).build()); users.findBySystemRole("ADMIN").forEach(admin->notifications.create(admin.getId(),"PROFILE_APPROVAL","Yêu cầu chỉnh sửa hồ sơ",requester.getFullName()+" đã gửi yêu cầu cập nhật hồ sơ.","/members")); return map(saved); }
 public List<ProfileChangeRequestResponse> pending(UserPrincipal current){ requireAdmin(current); return requests.findByStatusOrderByCreatedAtDesc("PENDING").stream().map(this::map).toList(); }
 public List<ProfileChangeRequestResponse> all(UserPrincipal current){ requireAdmin(current); return requests.findAllByOrderByCreatedAtDesc().stream().map(this::map).toList(); }
 public ProfileChangeRequestResponse review(Long id,boolean approved,String note,UserPrincipal current){ requireAdmin(current); ProfileChangeRequest change=requests.findById(id).orElseThrow(()->new ResourceNotFoundException("Profile change request not found")); if(!"PENDING".equals(change.getStatus())) throw new BadRequestException("Yêu cầu đã được xử lý."); User admin=users.findById(current.getId()).orElseThrow(()->new ResourceNotFoundException("User not found")); change.setStatus(approved?"APPROVED":"REJECTED"); change.setReviewNote(note); change.setReviewedBy(admin); change.setReviewedAt(LocalDateTime.now()); if(approved){ EmployeeProfileRequest payload=mapper.convertValue(change.getRequestedData(),EmployeeProfileRequest.class); profiles.updateProfile(change.getRequester().getId(),payload,UserPrincipal.create(admin)); } notifications.create(change.getRequester().getId(), approved?"PROFILE_APPROVED":"PROFILE_REJECTED", approved?"Hồ sơ đã được phê duyệt":"Yêu cầu chỉnh sửa bị từ chối", approved?"Thông tin hồ sơ của bạn đã được cập nhật.":(note==null||note.isBlank()?"Vui lòng kiểm tra lại thông tin hồ sơ.":note),"/profile"); return map(change); }
 private void requireAdmin(UserPrincipal current){if(current==null||!"ADMIN".equalsIgnoreCase(current.getSystemRole())) throw new BadRequestException("Chỉ admin được phê duyệt yêu cầu.");}
 private ProfileChangeRequestResponse map(ProfileChangeRequest r){return ProfileChangeRequestResponse.builder().id(r.getId()).requesterId(r.getRequester().getId()).requesterName(r.getRequester().getFullName()).requesterEmail(r.getRequester().getEmail()).requesterDepartmentName(r.getRequester().getDepartment()!=null?r.getRequester().getDepartment().getName():null).status(r.getStatus()).requestedData(r.getRequestedData()).reviewNote(r.getReviewNote()).createdAt(r.getCreatedAt()).reviewedAt(r.getReviewedAt()).build();}
}
